// Independent frontend. Only independent.wasm, art.js and audio.js are used.
(()=>{'use strict';
 const $=id=>document.getElementById(id),canvas=$('world'),c=canvas.getContext('2d'),mini=$('mini'),mc=mini.getContext('2d');
 let engine,state,selected=new Set(),activeBuilding=null,paused=true,menu=true,mission=0,difficulty=1,zoom=1,cam={x:0,y:0},drag=null,mouse={x:-1,y:-1},last=0,timeAccumulator=0,speed=1,commandMode='',muted=false;
 let sightMask=[];
 const enc=new TextEncoder(),dec=new TextDecoder(),keys=new Set(),seen=new Set();
 const names={grunt:'Grunts',psycho:'Psychos',tough:'Toughs',sniper:'Snipers',pyro:'Pyros',laser:'Lasers',jeep:'Jeep',light:'Leichter Panzer',medium:'Mittlerer Panzer',heavy:'Schwerer Panzer',apc:'Transporter',crane:'Kran',gatling:'Gatling',cannon:'Kanone',missile:'Raketengeschütz'};
 function call(v){const bytes=enc.encode(JSON.stringify(v)),ptr=engine.alloc(bytes.length);new Uint8Array(engine.memory.buffer,ptr,bytes.length).set(bytes);let n;try{n=engine.run(ptr,bytes.length);}finally{engine.free(ptr,bytes.length);}const s=JSON.parse(dec.decode(new Uint8Array(engine.memory.buffer,engine.output(),n)));if(s.error)throw Error(s.error);return s;}
 function update(s){state=s;updateSight();for(const e of s.events){if(e.kind==='capture'){if(e.team===0)RadioAudio.say('capture');else if(e.previous===0)RadioAudio.say('lost');}else if(e.team===0)RadioAudio.say(e.kind);}for(const id of selected)if(!s.units.some(u=>u.id===id))selected.delete(id);if(state.winner!==null){paused=true;$('newBattle').hidden=false;$('result').textContent=state.winner===0?'SIEG – Fort gesichert':'NIEDERLAGE';$('result').hidden=false;RadioAudio.say(state.winner===0?'victory':'defeat');}hud();}
 function start(){mission=+$('mission').value;difficulty=+$('difficulty').value;selected.clear();activeBuilding=null;seen.clear();timeAccumulator=0;$('factory').hidden=true;$('result').hidden=true;$('newBattle').hidden=true;update(call({op:'init',mission,difficulty,seed:991+mission*1501}));menu=false;paused=false;$('menu').hidden=true;$('pause').hidden=true;$('hud').hidden=false;zoom=Math.max(1,Math.min(2,innerHeight/(state.map.height*32)));const fort=state.buildings.find(b=>b.team===0&&b.kind==='fort');cam={x:fort.x+fort.w/2-innerWidth/zoom/2,y:fort.y+fort.h-innerHeight/zoom/2};clamp();RadioAudio.unlock();RadioAudio.say('start');}
 function resize(){canvas.width=innerWidth*devicePixelRatio;canvas.height=innerHeight*devicePixelRatio;canvas.style.width=innerWidth+'px';canvas.style.height=innerHeight+'px';}window.addEventListener('resize',resize);resize();
 function point(e){return {x:cam.x+e.clientX/zoom,y:cam.y+e.clientY/zoom};}
 function clamp(){if(!state)return;cam.x=Math.max(0,Math.min(state.map.width*32-innerWidth/zoom,cam.x));cam.y=Math.max(0,Math.min(state.map.height*32-innerHeight/zoom,cam.y));}
 function command(kind,extra={}){if(!selected.size)return;update(call({op:'command',kind,ids:[...selected],...extra}));}
 function context(p){const unit=state.units.find(u=>Math.hypot(u.x-p.x,u.y-p.y)<(u.type==='grunt'?16:24));const b=state.buildings.find(b=>p.x>b.x&&p.x<b.x+b.w&&p.y>b.y&&p.y<b.y+b.h);const mine=state.units.filter(u=>selected.has(u.id));
  if(unit&&unit.team<0&&mine.some(u=>state.catalog.find(d=>d.type===u.type).class===0))command('enter',{target:unit.id});
  else if(unit&&unit.team===0&&unit.type==='apc')command('board',{target:unit.id});
  else if(unit&&unit.team===1)command('attack',{target:unit.id});
  else if(b&&b.team!==0)command('attackBuilding',{target:b.id,x:b.x+b.w/2,y:b.y+b.h+24});
  else if(b&&b.team===0&&mine.some(u=>u.type==='crane'))command('repair',{target:b.id});
  else {const j=Math.floor(p.y/32)*state.map.width+Math.floor(p.x/32);if(state.map.bridgeBase[j]>=0&&mine.some(u=>u.type==='crane'))command('repairBridge',p);else if(state.map.bridgeBase[j]>=0&&commandMode==='attack')command('attackBridge',p);else command(commandMode||'move',p);}commandMode='';$('orderMode').textContent='';
 }
 canvas.oncontextmenu=e=>e.preventDefault();canvas.onpointerdown=e=>{if(!state||paused)return;RadioAudio.unlock();const p=point(e);if(e.button===2){context(p);return;}drag={start:p,end:p,sx:e.clientX,sy:e.clientY};canvas.setPointerCapture(e.pointerId);};
 canvas.onpointermove=e=>{mouse={x:e.clientX,y:e.clientY};if(drag)drag.end=point(e);};canvas.onpointerleave=()=>mouse={x:-1,y:-1};canvas.onpointerup=e=>{if(!drag||paused)return;const d=drag;drag=null;const p=point(e);const box=Math.hypot(e.clientX-d.sx,e.clientY-d.sy)>6;if(!e.shiftKey)selected.clear();if(box){for(const u of state.units)if(u.team===0&&u.x>=Math.min(d.start.x,p.x)&&u.x<=Math.max(d.start.x,p.x)&&u.y>=Math.min(d.start.y,p.y)&&u.y<=Math.max(d.start.y,p.y))selected.add(u.id);}else{const u=state.units.find(u=>u.team===0&&Math.hypot(u.x-p.x,u.y-p.y)<22);if(u){for(const member of state.units)if(member.team===0&&(e.ctrlKey?member.id===u.id:member.squad===u.squad))selected.add(member.id);RadioAudio.say('ready');}else{const b=state.buildings.find(b=>b.team===0&&p.x>b.x&&p.x<b.x+b.w&&p.y>b.y&&p.y<b.y+b.h);if(b)openFactory(b);}}hud();};
 canvas.onwheel=e=>{e.preventDefault();const p=point(e),before=zoom;zoom=Math.max(.7,Math.min(3,zoom+(e.deltaY<0?.15:-.15)));cam.x=p.x-e.clientX/zoom;cam.y=p.y-e.clientY/zoom;clamp();};
 window.addEventListener('keydown',e=>{if(e.target.matches('input,select'))return;keys.add(e.key.toLowerCase());if(e.key===' '){e.preventDefault();if(state){const b=state.buildings.find(b=>b.kind==='fort'&&b.team===0);cam.x=b.x-innerWidth/zoom/2;cam.y=b.y-innerHeight/zoom/2;clamp();}}if(e.key.toLowerCase()==='p'||e.key==='Escape')togglePause();if(e.key.toLowerCase()==='f'){commandMode='attack';$('orderMode').textContent='Angriffsziel mit Rechtsklick waehlen';}if(e.key.toLowerCase()==='u')command('unload');if(e.key.toLowerCase()==='x')command('stop');});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));
 function togglePause(){if(menu||!state)return;paused=!paused;$('pause').hidden=!paused;}
 function openFactory(b){activeBuilding=b.id;$('factory').hidden=false;factory();}
 function factory(){if(activeBuilding===null||!state)return;const b=state.buildings[activeBuilding];if(b.team!==0||b.hp<=0){$('factory').hidden=true;return;}$('buildingName').textContent=({fort:'Fort',robot:'Roboterfabrik',vehicle:'Fahrzeugfabrik',repair:'Werkstatt',radar:'Radarstation'}[b.kind])+' '+ '★'.repeat(b.stars);$('production').textContent=b.product?`${names[b.product]} · ${Math.floor(b.progress*100)} %`:'Keine Produktion';const sig=b.kind+b.stars;if($('products').dataset.sig!==sig){$('products').dataset.sig=sig;$('products').replaceChildren();for(const d of state.catalog.filter(d=>d.stars<=b.stars&&(b.kind==='fort'||b.kind==='robot'&&d.class===0||b.kind==='vehicle'&&d.class!==0))){const button=document.createElement('button');button.textContent=`${names[d.type]} (${d.members} / ${d.seconds}s)`;button.onclick=()=>update(call({op:'produce',id:activeBuilding,product:d.type}));$('products').append(button);}}}
 function hud(){if(!state)return;const owned=[0,1].map(t=>state.sectors.filter(s=>s.owner===t).length);$('status').textContent=`${Math.floor(state.time/60)}:${String(Math.floor(state.time%60)).padStart(2,'0')}   GEBIETE ${owned[0]} : ${owned[1]}   ${['LEICHT','NORMAL','SCHWER','BRUTAL'][difficulty]}`;$('selection').textContent=selected.size?`${selected.size} ausgewählt · Rechtsklick: Befehl · U: Aussteigen`:'Linksklick: Trupp auswählen · Rahmen: Mehrfachauswahl · Rechtsklick: Befehl';factory();}
 function sight(u){const d=state.catalog.find(d=>d.type===u.type);return Math.max(180,d.range+60);}
 function updateSight(){const m=state.map;sightMask=new Uint8Array(m.width*m.height);const observers=[...state.units.filter(u=>u.team===0).map(u=>({x:u.x,y:u.y,r:sight(u)})),...state.buildings.filter(b=>b.team===0&&b.hp>0).map(b=>({x:b.x+b.w/2,y:b.y+b.h/2,r:b.kind==='radar'?260+state.sectors.filter(s=>s.owner===0).length*45:170}))];for(const o of observers){for(let y=Math.max(0,Math.floor((o.y-o.r)/32));y<Math.min(m.height,(o.y+o.r)/32+1);y++)for(let x=Math.max(0,Math.floor((o.x-o.r)/32));x<Math.min(m.width,(o.x+o.r)/32+1);x++){if(Math.hypot(x*32+16-o.x,y*32+16-o.y)<o.r){const j=y*m.width+x;sightMask[j]=1;seen.add(j);}}}}
 function visible(x,y){return !!sightMask[Math.floor(y/32)*state.map.width+Math.floor(x/32)];}
 function draw(now){requestAnimationFrame(draw);const dt=Math.min(.1,(now-last)/1000||.016);last=now;if(!state)return;if(!paused){timeAccumulator+=dt*speed;while(timeAccumulator>=.05&&!paused){update(call({op:'tick',dt:.05}));timeAccumulator-=.05;}const scroll=420*dt/zoom;if(keys.has('a')||keys.has('arrowleft')||(mouse.x>=0&&mouse.x<12))cam.x-=scroll;if(keys.has('d')||keys.has('arrowright')||mouse.x>innerWidth-12)cam.x+=scroll;if(keys.has('w')||keys.has('arrowup')||(mouse.y>=0&&mouse.y<12))cam.y-=scroll;if(keys.has('s')||keys.has('arrowdown')||mouse.y>innerHeight-12)cam.y+=scroll;clamp();}
  c.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0);c.fillStyle='#172019';c.fillRect(0,0,innerWidth,innerHeight);c.scale(zoom,zoom);c.translate(-cam.x,-cam.y);c.imageSmoothingEnabled=false;IndependentArt.terrain(c,state.map);
  const m=state.map;for(let y=1;y<m.height;y++)for(let x=1;x<m.width;x++){const j=y*m.width+x,s=m.territory[j],owner=state.sectors[s].owner;c.fillStyle=owner===0?'#e86d53':owner===1?'#709de2':'#ddd1a0';if(m.territory[j-1]!==s)c.fillRect(x*32,y*32+12,2,2);if(m.territory[j-m.width]!==s)c.fillRect(x*32+12,y*32,2,2);}
  const items=[...state.buildings.map(b=>({y:b.y+b.h,b})),...state.units.map(u=>({y:u.y,u}))].sort((a,b)=>a.y-b.y);for(const item of items){if(item.b)IndependentArt.building(c,item.b,state.time);else{const u=item.u;if(u.team===1&&!visible(u.x,u.y))continue;IndependentArt.unit(c,u,state.time);if(selected.has(u.id)){c.strokeStyle='#fff2a6';c.lineWidth=1/zoom;c.strokeRect(u.x-13,u.y-20,26,30);}if(selected.has(u.id)||u.hp<u.maxHp){c.fillStyle='#1c241c';c.fillRect(u.x-12,u.y-25,24,3);c.fillStyle=u.hp/u.maxHp>.4?'#9dd372':'#e77c51';c.fillRect(u.x-12,u.y-25,24*u.hp/u.maxHp,2);}}}
  for(const s of state.sectors){if(s.home)continue;c.fillStyle='#303a2c';c.fillRect(s.x,s.y-29,2,30);c.fillStyle=s.owner===0?'#de6141':s.owner===1?'#548cce':'#d7cfad';c.beginPath();c.moveTo(s.x+2,s.y-29);c.lineTo(s.x+20,s.y-27+Math.sin(state.time*4+s.id)*2);c.lineTo(s.x+17,s.y-17);c.lineTo(s.x+2,s.y-18);c.fill();}
  for(const box of state.crates)if(!box.taken){c.fillStyle='#293a28';c.fillRect(box.x-7,box.y-5,14,10);c.fillStyle='#b0b66e';c.fillRect(box.x-5,box.y-4,10,2);c.fillStyle='#cbb563';c.fillRect(box.x-1,box.y-3,2,7);}
  IndependentArt.effects(c,state.effects,state.time);
  // Radar has an actual information role: unexplored ground is dim, enemy units need live sight.
  for(let y=0;y<m.height;y++)for(let x=0;x<m.width;x++){const j=y*m.width+x,v=visible(x*32+16,y*32+16);if(v)seen.add(j);if(!v){c.fillStyle=seen.has(j)?'#10201855':'#101a2477';c.fillRect(x*32,y*32,32,32);}}
  if(drag){c.strokeStyle='#f4e8b0';c.strokeRect(drag.start.x,drag.start.y,drag.end.x-drag.start.x,drag.end.y-drag.start.y);}minimap();
 }
 function minimap(){mc.fillStyle='#26392a';mc.fillRect(0,0,224,160);const m=state.map;for(let y=0;y<m.height;y++)for(let x=0;x<m.width;x++){mc.fillStyle=['#a79263','#7e7b5a','#4c5141','#457d8a','#667047','#b3a478'][m.tiles[y*m.width+x]];mc.fillRect(x*4,y*4,4,4);}for(const b of state.buildings){mc.fillStyle=b.team===0?'#ed795a':b.team===1?'#689ee7':'#ddd5ad';mc.fillRect(b.x/8,b.y/8,b.w/8,b.h/8);}for(const u of state.units)if(u.team===0||visible(u.x,u.y)){mc.fillStyle=u.team===0?'#ff9d71':'#91beff';mc.fillRect(u.x/8,u.y/8,2,2);}mc.strokeStyle='#fff0bd';mc.strokeRect(cam.x/8,cam.y/8,innerWidth/zoom/8,innerHeight/zoom/8);}
 mini.onpointerdown=e=>{const r=mini.getBoundingClientRect();cam.x=(e.clientX-r.left)/r.width*state.map.width*32-innerWidth/zoom/2;cam.y=(e.clientY-r.top)/r.height*state.map.height*32-innerHeight/zoom/2;clamp();};
 $('newBattle').onclick=()=>{if(state.winner===0)$('mission').value=Math.min(19,mission+1);start();};$('start').onclick=start;$('pauseButton').onclick=togglePause;$('resume').onclick=togglePause;$('quit').onclick=()=>{paused=true;menu=true;$('menu').hidden=false;$('pause').hidden=true;$('hud').hidden=true;};$('factoryClose').onclick=()=>{$('factory').hidden=true;activeBuilding=null;};$('cancelProduction').onclick=()=>update(call({op:'produce',id:activeBuilding,product:null}));$('attack').onclick=()=>{commandMode='attack';$('orderMode').textContent='Angriffsziel mit Rechtsklick waehlen';};$('stop').onclick=()=>command('stop');$('unload').onclick=()=>command('unload');$('speed').onclick=()=>{speed=speed===1?2:1;$('speed').textContent=speed+'x';};$('mute').onclick=()=>{muted=!muted;RadioAudio.mute(muted);$('mute').textContent=muted?'Ton aus':'Ton an';};
 for(const range of document.querySelectorAll('[data-audio]'))range.oninput=()=>{RadioAudio.unlock();RadioAudio.set(range.dataset.audio,range.value/100);};
 let radioTimer;window.addEventListener('radio',e=>{$('radio').textContent=e.detail;$('radio').hidden=false;clearTimeout(radioTimer);radioTimer=setTimeout(()=>$('radio').hidden=true,4500);});
 for(let i=0;i<20;i++){const o=document.createElement('option');o.value=i;o.textContent=`Mission ${i+1} / ${['Wüste','Vulkan','Eis','Dschungel','Stadt'][Math.floor(i/4)]}`;$('mission').append(o);}
 $('difficulty').onchange=()=>{$('difficultyInfo').textContent=['Mehr Startroboter, langsame KI.','Gleiche Produktionsbedingungen.','Schnellere KI-Produktion und Reaktion.','Hoher Produktionsdruck und schnelle Entscheidungen.'][+$('difficulty').value];};
 fetch('engine.wasm').then(r=>{if(!r.ok)throw Error('Engine nicht erreichbar');return r.arrayBuffer();}).then(bytes=>WebAssembly.instantiate(bytes,{})).then(r=>{engine=r.instance.exports;$('start').disabled=false;$('loading').textContent='Rust / WebAssembly bereit';}).catch(e=>$('loading').textContent=e.message);
 requestAnimationFrame(draw);
})();
